#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> l(n);
    for (int i = 0; i < n; ++i) {
        cin >> l[i];
    }
    vector<int> part1(l.begin(), l.begin() + n / 2);
    vector<int> part2(l.begin() + n / 2, l.end());

    int len_part1 = part1.size();
    int len_part2 = part2.size();

    int count1 = 1 << len_part1;
    int count2 = 1 << len_part2;

    vector<int> sums1;
    for (int mask = 0; mask < count1; ++mask) {
        int total = 0;
        for (int idx = 0; idx < len_part1; ++idx) {
            if (mask & (1 << idx)) {
                total += part1[idx];
            }
        }
        sums1.push_back(total % m);
    }

    vector<int> sums2;
    for (int mask = 0; mask < count2; ++mask) {
        int total = 0;
        for (int idx = 0; idx < len_part2; ++idx) {
            if (mask & (1 << idx)) {
                total += part2[idx];
            }
        }
        sums2.push_back(total % m);
    }

    std::sort(sums1.begin(), sums1.end());
    std::sort(sums2.begin(), sums2.end());

    int max_result = 0;

    auto binary_search_max = [](const vector<int>& l, int x) {
        int low = 0, high = (int)l.size() - 1;
        int ans = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (l[mid] < x) {
                ans = l[mid];
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    };

    for (int s : sums1) {
        int req = m - s;
        int val = binary_search_max(sums2, req);
        max_result = max(max_result, (s + val) % m);
    }

    cout << max_result << "\n";

    return 0;
}
